const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let text = '';
  if (item.binary && item.binary.data) {
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    text = buffer.toString('utf-8');
  }
  const meta = $('Find documents in Drive').item.json;
  results.push({ json: { content: text, title: meta.name || '', source: 'https://docs.google.com/document/d/' + meta.id + '/edit' } });
}
return results;

