const items = $input.all();
const allKeys = new Set();
items.forEach(it => Object.keys(it.json || {}).forEach(k => allKeys.add(k)));
const keyList = Array.from(allKeys);

function isHeaderRow(row) {
  const vals = keyList.map(k => row[k]).filter(v => v !== undefined && v !== null && v !== '');
  if (vals.length < 2) return false;
  const nonNumeric = vals.filter(v => typeof v !== 'number' && isNaN(Number(v)));
  return nonNumeric.length / vals.length > 0.6;
}

let currentHeaders = {};
let lines = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  if (isHeaderRow(row)) {
    const newHeaders = {};
    let mapped = 0;
    keyList.forEach(k => {
      if (row[k] !== undefined && row[k] !== null && row[k] !== '') {
        newHeaders[k] = String(row[k]);
        mapped++;
      }
    });
    if (mapped >= 2) {
      currentHeaders = newHeaders;
      lines.push('--- Section: ' + Object.values(newHeaders).join(' | ') + ' ---');
      continue;
    }
  }
  const parts = Object.keys(row)
    .filter(k => row[k] !== undefined && row[k] !== null && row[k] !== '')
    .map(k => (currentHeaders[k] || k) + ': ' + row[k]);
  if (parts.length) lines.push(parts.join(', '));
}
const text = lines.join('\n');
const meta = $('Find documents in Drive').item.json;
return [{ json: { content: text, title: meta.name || '', source: meta.webViewLink || ('https://drive.google.com/file/d/' + meta.id + '/view') } }];

