const items = $input.all();
const row = items.length > 0 ? items[0].json : null;
const original = $('Process documents one by one').item.json;
const alreadyIndexed = !!(row && row.fileId && row.modifiedTime === original.modifiedTime);
return [{ json: Object.assign({}, original, { alreadyIndexed: alreadyIndexed }) }];

const tableRows = $input.all().map(it => it.json);
const driveFiles = $('Find documents in Drive').all().map(it => it.json.id);
const driveSet = new Set(driveFiles);
const orphans = tableRows.filter(r => r.fileId && !driveSet.has(r.fileId));
return orphans.map(r => ({ json: { fileId: r.fileId } }));

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const item = $input.item.json;
const mimeType = $input.item.binary.data.mimeType;
return { json: Object.assign({}, item, { imageBase64: base64, imageMimeType: mimeType }) };
